#include <bits/stdc++.h>
using namespace std;
#define LL long long
#define MAX_LIMIT 250005

int Mod;

int fastExponentiation(int base, int exponent) {
    LL result=1, current=base;
    while (exponent>0) {
        if (exponent & 1) result=result*current%Mod;
        current=current*current%Mod;
        exponent>>=1;
    }
    return (int)result;
}

int n, k;
int fact[MAX_LIMIT], inv_fact[MAX_LIMIT], inv[MAX_LIMIT], cache[19][MAX_LIMIT];

int recursiveSolve(int used, int subset) {
    if (cache[used][subset]!=-1) return cache[used][subset];
    int answer=0;
    if (subset==0) {
        answer=fact[n];
        for (int i=1;i<=used;++i)
            answer=1LL*answer*(k-i+1)%Mod;
        return cache[used][subset]=answer;
    }
    if (used>k) return 0;
    int lowest_bit = subset & (-subset);
    int remaining = subset - lowest_bit;
    for (int T=remaining;; T=(T-1)&remaining) {
        answer=(answer+1LL*inv_fact[subset - T]*recursiveSolve(used+1,T)%Mod)%Mod;
        if (T==0) break;
    }
    return cache[used][subset]=answer;
}

int main() {
    scanf("%d%d%d",&n,&k,&Mod);
    if (n%2==1) {
        printf("%d\n",fastExponentiation(k,n));
        return 0;
    }
    fact[0]=inv_fact[0]=1;
    fact[1]=inv_fact[1]=1;
    for (int i=2;i<=n;++i) {
        fact[i]=1LL*fact[i-1]*i%Mod;
        inv[i]=1LL*(Mod - Mod/i)*inv[Mod%i]%Mod;
        inv_fact[i]=1LL*inv_fact[i-1]*inv[i]%Mod;
    }
    for (int i=0;i<=18;++i)
        for (int j=0;j<=n;++j)
            cache[i][j]=-1;
    printf("%d\n",(fastExponentiation(k,n)-recursiveSolve(0,n)+Mod)%Mod);
    return 0;
}
